export const CATALOG_ITEMS = CATALOG_RAW;

/**
 * Seçilmiş öneri grubu (Zevk Haritası güncellemesinden sonraki `picked` gibi).
 * `mapRecommendationBatchToDisplayItems` için gerekli sarmalayıcı biçim.
 */
export const BATCH_ENTRIES = [201, 202, 204, 207, 210, 213, 214].map((id, index) => {
  const candidate = CATALOG_RAW.find((item) => item.id === id);
  return {
    candidate: { ...candidate },
    tags: [`faz6-${candidate.media_type}`, `sıra-${index}`],
    score: 80 - index,
    ...(index === 0 ? { selectionRing: 'ring1' } : {}),
  };
});
